window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-65c067ef543a569b"]={"versions": [{"id": "FIG-65c067ef543a569b", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_AliveSupervision</code>) im Kontext des AUTOSAR Health Monitoring (Adaptive Platform). Das Diagramm spezifiziert das statische Metamodell für die Alive-Überwachung (Alive Supervision) von Kontrollpunkten (Checkpoints).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Entitäten sowie eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong><code>AliveSupervision</code></strong> (Klasse): Repräsentiert die Konfiguration der Alive-Überwachung mit folgenden privaten Attributen:\n<ul class=\"fig-list\"><li><code>- AliveReferenceCycle</code>\n</li><li><code>- ExpectedAliveIndications</code>\n</li><li><code>- MaxMargin</code>\n</li><li><code>- MinMargin</code>\n</li></ul>\n</li><li><strong><code>Checkpoint</code></strong> (Klasse): Repräsentiert den zu überwachenden Kontrollpunkt.\n</li><li><strong><code>SupervisedCheckpoint</code></strong> (gerichtete Assoziation): Ausgehend von <code>AliveSupervision</code> hin zu <code>Checkpoint</code> mit der Zielkardinalität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält das Diagramm keine explizite Ablauf- oder Sequenzdarstellung. Fachlich referenziert eine Instanz von <code>AliveSupervision</code> genau einen <code>Checkpoint</code> (<code>SupervisedCheckpoint</code>). Innerhalb des definierten Überwachungszyklus (<code>AliveReferenceCycle</code>) wird geprüft, ob die Anzahl der eingegangenen Alive-Meldungen des Checkpoints der erwarteten Anzahl (<code>ExpectedAliveIndications</code>) unter Berücksichtigung der zulässigen Toleranzgrenzen (<code>MinMargin</code>, <code>MaxMargin</code>) entspricht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend ist die Modellstruktur für die Konfiguration des Health Management:</p>\n<ul class=\"fig-list\"><li>Jede Alive-Überwachungsinstanz ist exakt einem Ziel-Checkpoint zugeordnet (Multiplizität <code>1</code>).\n</li><li>Konfigurationsparameter umfassen den Auswertezyklus (<code>AliveReferenceCycle</code>), die erwartete Häufigkeit (<code>ExpectedAliveIndications</code>) sowie untere und obere Toleranzen (<code>MinMargin</code>, <code>MaxMargin</code>).\n</li><li>Entwickler und Integratoren müssen sicherstellen, dass die Zykluszeit und Margen konsistent zur Ausführungsfrequenz der überwachten Entität parametriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eb31467d2c0d6a0c", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_AliveSupervision</code>) im Kontext des AUTOSAR Health Monitoring (Adaptive Platform). Das Diagramm spezifiziert das statische Metamodell für die Alive-Überwachung (Alive Supervision) von Kontrollpunkten (Checkpoints).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Entitäten sowie eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong><code>AliveSupervision</code></strong> (Klasse): Repräsentiert die Konfiguration der Alive-Überwachung mit folgenden privaten Attributen:\n<ul class=\"fig-list\"><li><code>- ReferenceCycle</code>\n</li><li><code>- ExpectedAliveIndications</code>\n</li><li><code>- MaxMargin</code>\n</li><li><code>- MinMargin</code>\n</li></ul>\n</li><li><strong><code>Checkpoint</code></strong> (Klasse): Repräsentiert den zu überwachenden Kontrollpunkt.\n</li><li><strong><code>SupervisedCheckpoint</code></strong> (gerichtete Assoziation): Ausgehend von <code>AliveSupervision</code> hin zu <code>Checkpoint</code> mit der Zielkardinalität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält das Diagramm keine explizite Ablauf- oder Sequenzdarstellung. Fachlich referenziert eine Instanz von <code>AliveSupervision</code> genau einen <code>Checkpoint</code> (<code>SupervisedCheckpoint</code>). Innerhalb des definierten Referenzzyklus (<code>ReferenceCycle</code>) wird geprüft, ob die Anzahl der eingegangenen Alive-Meldungen des Checkpoints der erwarteten Anzahl (<code>ExpectedAliveIndications</code>) unter Berücksichtigung der zulässigen Toleranzgrenzen (<code>MinMargin</code>, <code>MaxMargin</code>) entspricht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend ist die Modellstruktur für die Konfiguration des Health Management:</p>\n<ul class=\"fig-list\"><li>Jede Alive-Überwachungsinstanz ist exakt einem Ziel-Checkpoint zugeordnet (Multiplizität <code>1</code>).\n</li><li>Konfigurationsparameter umfassen den Referenzzyklus (<code>ReferenceCycle</code>), die Soll-Anzahl der Meldungen (<code>ExpectedAliveIndications</code>) sowie die Toleranzgrenzen (<code>MinMargin</code>, <code>MaxMargin</code>).\n</li><li>Entwickler und Integratoren müssen die Parametrierung von <code>ReferenceCycle</code> und Margen auf die tatsächliche Aufruffrequenz des überwachten Checkpoints abstimmen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-674a4f9ad91eaf90", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_AliveSupervision</code>) im Kontext des AUTOSAR Health Monitoring (Adaptive Platform). Das Diagramm spezifiziert das statische Metamodell für die Alive-Überwachung (Alive Supervision) von Kontrollpunkten (Checkpoints).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Entitäten sowie eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong><code>AliveSupervision</code></strong> (Klasse): Repräsentiert die Konfiguration der Alive-Überwachung mit folgenden privaten Attributen:\n<ul class=\"fig-list\"><li><code>- AliveReferenceCycle</code>\n</li><li><code>- ExpectedAliveIndications</code>\n</li><li><code>- MaxMargin</code>\n</li><li><code>- MinMargin</code>\n</li></ul>\n</li><li><strong><code>Checkpoint</code></strong> (Klasse): Repräsentiert den zu überwachenden Kontrollpunkt.\n</li><li><strong><code>SupervisedCheckpoint</code></strong> (gerichtete Assoziation): Ausgehend von <code>AliveSupervision</code> hin zu <code>Checkpoint</code> mit der Zielkardinalität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält das Diagramm keine explizite Ablauf- oder Sequenzdarstellung. Fachlich referenziert eine Instanz von <code>AliveSupervision</code> genau einen <code>Checkpoint</code> (<code>SupervisedCheckpoint</code>). Innerhalb des definierten Überwachungszyklus (<code>AliveReferenceCycle</code>) wird geprüft, ob die Anzahl der eingegangenen Alive-Meldungen des Checkpoints der erwarteten Anzahl (<code>ExpectedAliveIndications</code>) unter Berücksichtigung der zulässigen Toleranzgrenzen (<code>MinMargin</code>, <code>MaxMargin</code>) entspricht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend ist die Modellstruktur für die Konfiguration des Health Management:</p>\n<ul class=\"fig-list\"><li>Jede Alive-Überwachungsinstanz ist exakt einem Ziel-Checkpoint zugeordnet (Multiplizität <code>1</code>).\n</li><li>Konfigurationsparameter umfassen den Auswertezyklus (<code>AliveReferenceCycle</code>), die erwartete Häufigkeit (<code>ExpectedAliveIndications</code>) sowie untere und obere Toleranzen (<code>MinMargin</code>, <code>MaxMargin</code>).\n</li><li>Entwickler und Integratoren müssen sicherstellen, dass die Zykluszeit und Margen konsistent zur Ausführungsfrequenz der überwachten Entität parametriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-65c067ef543a569b", "to": "FIG-eb31467d2c0d6a0c", "fr": "R1.5.1", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut in Klasse <code>AliveSupervision</code>: Attributname lautet <code>ReferenceCycle</code> statt zuvor <code>AliveReferenceCycle</code>.\n</li></ul>"}, {"from": "FIG-eb31467d2c0d6a0c", "to": "FIG-65c067ef543a569b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut in Klasse <code>AliveSupervision</code>: Attributname lautet wieder <code>AliveReferenceCycle</code> statt <code>ReferenceCycle</code>.\n</li></ul>"}, {"from": "FIG-65c067ef543a569b", "to": "FIG-674a4f9ad91eaf90", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
